# PostgreSQL Connection Pool in Node.js

## Installation

```bash
npm install pg
```

## Basic Pool Setup

```javascript
// db/pool.js
const { Pool } = require('pg');

const pool = new Pool({
  // Connection settings
  host: process.env.DB_HOST || 'localhost',
  port: process.env.DB_PORT || 5432,
  database: process.env.DB_NAME,
  user: process.env.DB_USER,
  password: process.env.DB_PASSWORD,

  // Pool sizing
  max: 20,                    // Maximum connections in pool
  min: 2,                     // Minimum idle connections maintained
  idleTimeoutMillis: 30000,   // Remove idle connections after 30s
  connectionTimeoutMillis: 5000, // Fail if can't connect within 5s

  // Query timeout (requires pg >= 8.x)
  statement_timeout: 10000,   // Kill queries running over 10s
  query_timeout: 10000,       // Client-level query timeout

  // SSL (for production/cloud databases)
  ssl: process.env.NODE_ENV === 'production'
    ? { rejectUnauthorized: true, ca: process.env.DB_SSL_CERT }
    : false,
});

module.exports = pool;
```

## Error Handling & Monitoring

```javascript
// db/pool.js (extended)
const { Pool } = require('pg');

const pool = new Pool({ /* config above */ });

// Handle unexpected errors on idle clients
// Without this, errors crash the process
pool.on('error', (err, client) => {
  console.error('Unexpected error on idle client:', err.message);
  // Don't exit - pool will remove the broken client automatically
});

// Optional: Monitor pool lifecycle
pool.on('connect', (client) => {
  console.debug(`New client connected. Pool size: ${pool.totalCount}`);
});

pool.on('acquire', (client) => {
  console.debug(`Client acquired. Idle: ${pool.idleCount}, Waiting: ${pool.waitingCount}`);
});

pool.on('remove', (client) => {
  console.debug(`Client removed. Pool size: ${pool.totalCount}`);
});

module.exports = pool;
```

## Query Wrapper with Retry Logic

```javascript
// db/query.js
const pool = require('./pool');

class DatabaseError extends Error {
  constructor(message, { query, params, cause } = {}) {
    super(message);
    this.name = 'DatabaseError';
    this.query = query;
    this.params = params;
    this.cause = cause;
  }
}

/**
 * Execute a query with automatic retry on transient failures
 */
async function query(text, params, { retries = 3, retryDelay = 500 } = {}) {
  let lastError;

  for (let attempt = 1; attempt <= retries; attempt++) {
    try {
      const start = Date.now();
      const result = await pool.query(text, params);
      const duration = Date.now() - start;

      if (duration > 1000) {
        console.warn(`Slow query detected (${duration}ms):`, text);
      }

      return result;
    } catch (err) {
      lastError = err;

      // Only retry on transient/connection errors, not logic errors
      const isRetryable = isRetryableError(err);

      if (!isRetryable || attempt === retries) {
        throw new DatabaseError(`Query failed: ${err.message}`, {
          query: text,
          params,
          cause: err,
        });
      }

      console.warn(`Query attempt ${attempt} failed, retrying in ${retryDelay}ms...`);
      await sleep(retryDelay * attempt); // Exponential backoff
    }
  }
}

function isRetryableError(err) {
  const retryableCodes = new Set([
    '08000', // connection_exception
    '08003', // connection_does_not_exist
    '08006', // connection_failure
    '57P01', // admin_shutdown
    '57P02', // crash_shutdown
    '57P03', // cannot_connect_now
    '40001', // serialization_failure (deadlock)
    '40P01', // deadlock_detected
  ]);

  return retryableCodes.has(err.code) || err.message.includes('timeout');
}

const sleep = (ms) => new Promise((resolve) => setTimeout(resolve, ms));

module.exports = { query, DatabaseError };
```

## Transaction Helper

```javascript
// db/transaction.js
const pool = require('./pool');
const { DatabaseError } = require('./query');

/**
 * Execute multiple queries in a transaction with automatic rollback
 * @param {Function} callback - Receives a query function scoped to the transaction
 */
async function withTransaction(callback) {
  const client = await pool.connect();

  try {
    await client.query('BEGIN');

    // Scoped query function - uses this client, not the pool
    const transactionQuery = (text, params) => client.query(text, params);

    const result = await callback(transactionQuery);

    await client.query('COMMIT');
    return result;
  } catch (err) {
    await client.query('ROLLBACK').catch((rollbackErr) => {
      console.error('Rollback failed:', rollbackErr.message);
    });

    throw err instanceof DatabaseError
      ? err
      : new DatabaseError(`Transaction failed: ${err.message}`, { cause: err });
  } finally {
    client.release(); // Always return client to pool
  }
}

module.exports = { withTransaction };
```

## Usage Examples

```javascript
// services/userService.js
const { query } = require('../db/query');
const { withTransaction } = require('../db/transaction');

// Simple query
async function getUserById(id) {
  const { rows } = await query(
    'SELECT id, name, email FROM users WHERE id = $1',
    [id]
  );
  return rows[0] ?? null;
}

// Transaction example
async function transferFunds(fromId, toId, amount) {
  return withTransaction(async (txQuery) => {
    // Both queries use the same connection/transaction
    await txQuery(
      'UPDATE accounts SET balance = balance - $1 WHERE id = $2',
      [amount, fromId]
    );

    await txQuery(
      'UPDATE accounts SET balance = balance + $1 WHERE id = $2',
      [amount, toId]
    );

    const { rows } = await txQuery(
      'INSERT INTO transfers (from_id, to_id, amount) VALUES ($1, $2, $3) RETURNING id',
      [fromId, toId, amount]
    );

    return rows[0];
  });
}
```

## Graceful Shutdown

```javascript
// server.js
const pool = require('./db/pool');

async function shutdown(signal) {
  console.log(`Received ${signal}. Closing database pool...`);

  try {
    await pool.end(); // Waits for active queries to finish
    console.log('Pool closed successfully');
    process.exit(0);
  } catch (err) {
    console.error('Error closing pool:', err);
    process.exit(1);
  }
}

process.on('SIGTERM', () => shutdown('SIGTERM'));
process.on('SIGINT', () => shutdown('SIGINT'));
```

## Pool Sizing Guidelines

| Scenario | `max` | `min` |
|---|---|---|
| Development | 5 | 1 |
| Small production | 10 | 2 |
| High-traffic API | 20–50 | 5 |
| Serverless/Lambda | 1–2 | 0 |

> **Key rule:** `max` connections across all app instances should not exceed your PostgreSQL `max_connections` limit (default: 100). Use **PgBouncer** as a proxy if you need more.

## Common Pitfalls

```javascript
// ❌ Never do this - leaks the client if query throws
const client = await pool.connect();
await client.query('SELECT 1');
client.release();

// ✅ Always use try/finally
const client = await pool.connect();
try {
  await client.query('SELECT 1');
} finally {
  client.release(); // Runs even if query throws
}

// ✅ Or just use pool.query() for single queries (handles this automatically)
await pool.query('SELECT 1');
```

The most critical points are: **always release clients in a `finally` block**, **handle the pool `error` event** to prevent crashes, and **size your pool** based on your PostgreSQL server's `max_connections`.
